int fd = open("data.txt", O_RDWR | O_CREAT, 0666); // 1. Syscall Trap
if (fd < 0) { /* handle error */ }

char buffer[100];
ssize_t n = read(fd, buffer, 100); // 2. Kernel reads disk block

// After read completes, CPU returns to user mode
if (n == -1) {
    if (errno == EINTR) { // ECF: Signal delivery interrupted
        // Must typically restart the read()
    }
}
close(fd);

int sockfd = socket(AF_INET, SOCK_STREAM, 0);

// Syscall blocks process until connection established
if (connect(sockfd, (SA*)&servaddr, len) < 0) {
    // Syscall failure
}

// Data transfer syscalls
send(sockfd, "request", 7, 0);
recv(sockfd, buffer, 100, 0);

shutdown(sockfd, SHUT_RDWR); // Graceful close
close(sockfd);
